package com.franco.desco.adapter.out.sqlserver.fieldtrip;
import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.fieldtrip.*;import com.franco.desco.application.fieldtrip.port.out.FieldTripPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.fieldtrip.FieldTripModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class FieldTripSqlServerAdapter implements FieldTripPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,program,update,cancel,finish;
 public FieldTripSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("campo","PA_SalidaCampo_Sel_Listado","items");get=f.callWithResultSets("campo","PA_SalidaCampo_Sel_DetalleCompleto","header","participants","resources","assets","visits");program=f.callWithResultSets("campo","PA_SalidaCampo_Ins_Programar","createdParticipants","createdHeader");update=f.call("campo","PA_SalidaCampo_Upd_Registro");cancel=f.call("campo","PA_SalidaCampo_Upd_Cancelar");finish=f.call("campo","PA_SalidaCampo_Upd_Finalizar");}
 public PersistenceResult<PageResult<FieldTripModels.Summary>> list(FieldTripCommands.ListTrips c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,Map.of("filtros",map("estadoProceso",f==null?null:f.estadoProceso(),"motivoSalidaId",f==null?null:f.motivoSalidaId(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta(),"pagina",pg.pagina(),"tamanoPagina",pg.tamanio())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar las salidas.");}
 public PersistenceResult<FieldTripModels.Detail> get(FieldTripCommands.GetTrip c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("filtros",Map.of("salidaCampoId",c.salidaCampoId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la salida."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La salida seleccionada no está disponible.");var s=summary(h);return PersistenceResult.ok(PaAdapterSupport.message(out,"Salida consultada correctamente."),new FieldTripModels.Detail(s,SqlValues.string(h,"motivoCodigo"),rows(out,"participants").stream().map(this::participant).toList(),rows(out,"resources").stream().map(this::resource).toList(),rows(out,"assets").stream().map(this::asset).toList(),rows(out,"visits").stream().map(this::visit).toList()));}
 public PersistenceResult<Long> program(FieldTripCommands.Program c,SessionIdentity i,RequestMetadata m){var payload=write(i,m,c,Map.of("salida",map("motivoSalidaId",c.motivoSalidaId(),"fechaHoraProgramada",c.fechaHoraProgramada(),"descripcion",c.descripcion()),"participantes",c.participantes()==null?List.of():c.participantes().stream().map(x->map("empleadoId",x.empleadoId(),"funcion",x.funcion(),"esResponsable",x.esResponsable())).toList()));var out=e.executeJson(program,payload);return PaAdapterSupport.result(out,SqlValues.longValue(out,"nSalidaCampoId"),"No se pudo programar la salida.");}
 public PersistenceResult<Void> update(FieldTripCommands.Update c,SessionIdentity i,RequestMetadata m){var payload=write(i,m,c,Map.of("salida",map("salidaCampoId",c.salidaCampoId(),"motivoSalidaId",c.motivoSalidaId(),"fechaHoraProgramada",c.fechaHoraProgramada(),"descripcion",c.descripcion()),"participantes",c.participantes()==null?List.of():c.participantes().stream().map(x->map("empleadoId",x.empleadoId(),"funcion",x.funcion(),"esResponsable",x.esResponsable())).toList()));return voidResult(e.executeJson(update,payload),"No se pudo actualizar la salida.");}
 public PersistenceResult<Void> cancel(FieldTripCommands.Cancel c,SessionIdentity i,RequestMetadata m){return voidResult(e.executeJson(cancel,write(i,m,c,Map.of("salida",map("salidaCampoId",c.salidaCampoId(),"motivo",c.motivo())))),"No se pudo cancelar la salida.");}
 public PersistenceResult<Void> finish(FieldTripCommands.Finish c,SessionIdentity i,RequestMetadata m){return voidResult(e.executeJson(finish,write(i,m,c,Map.of("salida",map("salidaCampoId",c.salidaCampoId(),"fechaHoraRetornoReal",c.fechaHoraRetornoReal(),"motivo",c.motivo())))),"No se pudo finalizar la salida.");}
 private Map<String,Object> write(SessionIdentity i,RequestMetadata m,Object b,Map<String,Object> x){return pf.forWrite(i,m,b,x);}private PersistenceResult<Void> voidResult(Map<String,Object> o,String f){return PaAdapterSupport.result(o,null,f);}private List<Map<String,Object>> rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object> one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object> map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}
 private FieldTripModels.Summary summary(Map<String,Object>r){return new FieldTripModels.Summary(SqlValues.longValue(r,"salidaCampoId"),SqlValues.intValue(r,"motivoSalidaId"),SqlValues.string(r,"motivo"),SqlValues.instant(r,"fechaHoraProgramada"),SqlValues.instant(r,"fechaHoraSalidaReal"),SqlValues.instant(r,"fechaHoraRetornoReal"),SqlValues.string(r,"descripcion"),SqlValues.string(r,"estadoProceso"),SqlValues.bool(r,"estado"),SqlValues.longValue(r,"participantes"),SqlValues.longValue(r,"recursosProgramados"));}
 private FieldTripModels.Participant participant(Map<String,Object>r){return new FieldTripModels.Participant(SqlValues.longValue(r,"salidaParticipanteId"),SqlValues.longValue(r,"empleadoId"),SqlValues.string(r,"codigoEmpleado"),SqlValues.string(r,"nombres"),SqlValues.string(r,"apellidoPaterno"),SqlValues.string(r,"apellidoMaterno"),SqlValues.string(r,"funcion"),SqlValues.bool(r,"esResponsable"),SqlValues.bool(r,"estado"));}
 private FieldTripModels.Resource resource(Map<String,Object>r){return new FieldTripModels.Resource(SqlValues.longValue(r,"recursoProgramadoId"),SqlValues.longValue(r,"bienInventarioId"),SqlValues.string(r,"codigoPatrimonial"),SqlValues.string(r,"bienNombre"),SqlValues.longValue(r,"suministroId"),SqlValues.string(r,"suministroCodigo"),SqlValues.string(r,"suministroNombre"),SqlValues.string(r,"unidadMedida"),SqlValues.decimal(r,"cantidadProgramada"),SqlValues.string(r,"observacion"),SqlValues.string(r,"estado"),SqlValues.decimal(r,"cantidadEjecutada"));}
 private FieldTripModels.Asset asset(Map<String,Object>r){return new FieldTripModels.Asset(SqlValues.longValue(r,"salidaBienId"),SqlValues.longValue(r,"bienInventarioId"),SqlValues.string(r,"codigoPatrimonial"),SqlValues.string(r,"nombre"),SqlValues.instant(r,"fechaHoraEntrega"),SqlValues.instant(r,"fechaHoraDevolucion"),SqlValues.string(r,"estadoEntrega"),SqlValues.string(r,"estadoDevolucion"),SqlValues.string(r,"observacion"),SqlValues.bool(r,"estado"));}
 private FieldTripModels.Visit visit(Map<String,Object>r){return new FieldTripModels.Visit(SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.longValue(r,"salidaParticipanteId"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.instant(r,"fechaHoraInicio"),SqlValues.instant(r,"fechaHoraFin"),SqlValues.string(r,"estadoProceso"),SqlValues.bool(r,"estado"));}
}
